	void AddCardToQueue(object[] paraArray)
	{
		UICardSimpleControl cardControl = (UICardSimpleControl)paraArray[0];
		if (cardControl != null && !m_CardActionQueue.Contains(cardControl) && CurrentEffectCard != cardControl)
		{
			for (int i = 0; i < m_EnvPanels.Count; i++)
			{
				UICardSimpleControl lastCard = GetLastEnvCard(i);
				if (lastCard != null)
				{
					lastCard.UpdateBuffValue();
				}
			}
			if (cardControl.gameObject.activeSelf)
			{
				m_CardActionQueue.Enqueue(cardControl);
				CardActionQueueDebug = new List<UICardSimpleControl>(m_CardActionQueue);
				CardCtsDictDebug = new List<UICardSimpleControl>(m_CardCtsDict.Keys);
			}
			CheckAndSpawnKeyPath();
		}
	}

	void AddEffectValueToBagCard(object[] paraArray)
	{
		ECardType targetCardType = paraArray.Length > 0 && paraArray[0] is ECardType ? (ECardType)paraArray[0] : ECardType.attack;
		EEffectType effectType = paraArray.Length > 1 && paraArray[1] is EEffectType ? (EEffectType)paraArray[1] : EEffectType.Other;
		int value = paraArray.Length > 2 && paraArray[2] is int ? (int)paraArray[2] : 0;
		AddEffectValueToBagCard(targetCardType, effectType, value);
	}

	void Update()
	{
		if (CurrentEffectCard == null && m_CardActionQueue.Count > 0)
		{
			CurrentEffectCard = m_CardActionQueue.Dequeue();
			CardActionQueueDebug = new List<UICardSimpleControl>(m_CardActionQueue);
			CardCtsDictDebug = new List<UICardSimpleControl>(m_CardCtsDict.Keys);
			if (CurrentEffectCard != null)
			{
				GetOrCreateCardToken(CurrentEffectCard);
				CurrentEffectCard.OnBtnRealClick();
			}
		}

		if (CurrentEffectCard != null && !CurrentEffectCard.IsEffecting && m_CardCtsDict.Count == 0)
		{
			CurrentEffectCard = null;
		}
	}

	void LateUpdate()
	{
	}

	private bool HasAnyMonsterInEnv()
	{
		foreach (var kvp in m_EnvCardDict)
		{
			if (kvp.Value != null)
			{
				foreach (var card in kvp.Value)
				{
					if (card != null && card.gameObject.activeSelf && card.CardType == ECardType.monster)
					{
						return true;
					}
				}
			}
		}
		return false;
	}

	private void CheckAndSpawnKeyPath()
	{
		if (m_KeyPathSpawned)
		{
			return;
		}

		if (!HasAnyMonsterInEnv())
		{
			SpawnKeyPath();
		}
	}

	private void SpawnKeyPath()
	{
		m_KeyPathSpawned = true;

		if (m_KeyPathCardCache != null)
		{
			m_KeyPathCardCache.gameObject.SetActive(true);
			m_KeyPathCardCache.CacheTrans.SetAsLastSibling();
			m_KeyPathCardCache.PlayVFX(new List<EVFXName>(), ECardAnimName.UI_Carditem_pailai, EVFXLife.CardLife);
			Debug.Log($"KeyPath spawned at column 2 - all monsters cleared!");
		}
	}

	public void ClearCardQueue()
	{
		if (CurrentEffectCard != null)
		{
			CurrentEffectCard.IsEffecting = false;
			RemoveCardCts(CurrentEffectCard);
			CurrentEffectCard.Return();
		}
		CurrentEffectCard = null;

		while (m_CardActionQueue.Count > 0)
		{
			UICardSimpleControl cardControl = m_CardActionQueue.Dequeue();
			cardControl.IsEffecting = false;
			RemoveCardCts(cardControl);
			cardControl.Return();
		}
		CardActionQueueDebug = null;
		CardCtsDictDebug = null;

	}

